const menuData = [
  // DRY SNACKS
  { id: 1, name: "Matri", category: "Dry Snacks", prices: { "1KG": 250, "1/2KG": 130, "250GM": 65 }, imagePrompt: "Realistic high-quality macro food photography of Indian crispy Matri on a rustic plate", unsplashId: "food-1" },
  { id: 2, name: "Methi Matri", category: "Dry Snacks", prices: { "1KG": 250, "1/2KG": 130, "250GM": 65 }, imagePrompt: "Realistic high-quality macro food photography of green speckled fenugreek Methi Matri", unsplashId: "food-2" },
  { id: 3, name: "Namkeen Para", category: "Dry Snacks", prices: { "1KG": 250, "1/2KG": 130, "250GM": 65 }, imagePrompt: "Realistic high-quality macro photography of diamond-shaped crispy Namkeen Para", unsplashId: "food-3" },
  { id: 4, name: "Kaju Masala Para", category: "Dry Snacks", prices: { "1KG": 300, "1/2KG": 150, "250GM": 75 }, imagePrompt: "Realistic high-quality photography of cashew-shaped spiced Kaju Masala Para", unsplashId: "food-4" },
  { id: 5, name: "Dry Samosa", category: "Dry Snacks", prices: { "1KG": 280, "1/2KG": 145, "250GM": 150 }, imagePrompt: "Realistic photography of mini dry samosas filled with spices", unsplashId: "food-5" },
  { id: 6, name: "Murmura/Bhel", category: "Dry Snacks", prices: { "1KG": 300, "1/2KG": 150, "250GM": 75 }, imagePrompt: "Realistic street-style photography of spicy Murmura Bhel mix", unsplashId: "food-6" },
  { id: 7, name: "Nagpuri Poha", category: "Dry Snacks", prices: { "1KG": 320, "1/2KG": 165, "250GM": 85 }, imagePrompt: "Realistic high-quality photography of crispy dry Nagpuri Poha chivda", unsplashId: "food-7" },
  // NAMKEEN
  { id: 8, name: "Chakli", category: "Namkeen", prices: { "1KG": 300, "1/2KG": 150, "250GM": 80 }, imagePrompt: "Realistic high-quality photography of golden spiral crunchy Chakli", unsplashId: "food-8" },
  { id: 9, name: "Sev/Namkeen", category: "Namkeen", prices: { "1KG": 300, "1/2KG": 150, "250GM": 75 }, imagePrompt: "Realistic high-quality photography of fine besan Sev namkeen in a bowl", unsplashId: "food-9" },
  { id: 10, name: "Palak/Tamater Sev", category: "Namkeen", prices: { "1KG": 300, "1/2KG": 150, "250GM": 75 }, imagePrompt: "Realistic photography of green and red tinted spicy Sev (Palak and Tomato flavor)", unsplashId: "food-10" },
  // SWEETS (Longer Shelf Life)
  { id: 11, name: "Mitha Para", category: "Sweets", prices: { "1KG": 300, "1/2KG": 150, "250GM": 80 }, imagePrompt: "Realistic photography of sweet diamond-cut Mitha Para", unsplashId: "food-11" },
  { id: 12, name: "Mitha Para Ghee", category: "Sweets", prices: { "1KG": 450, "1/2KG": 230, "250GM": 120 }, imagePrompt: "Realistic photography of rich ghee-fried Mitha Para, golden and glossy", unsplashId: "food-12" },
  { id: 13, name: "Mitha Sugarkoted", category: "Sweets", prices: { "1KG": 320, "1/2KG": 165, "250GM": 85 }, imagePrompt: "Realistic photography of sugar-coated sweet bites (Shakarpara)", unsplashId: "food-13" },
  { id: 14, name: "Mitha Goudkoted", category: "Sweets", prices: { "1KG": 400, "1/2KG": 210, "250GM": 110 }, imagePrompt: "Realistic photography of jaggery-coated sweet bites (Gudpara)", unsplashId: "food-14" },
  // WET/FRESH SWEETS
  { id: 15, name: "Modak Mawa", category: "Wet Sweets", prices: { "1KG": 550, "1/2KG": 280, "250GM": 140 }, imagePrompt: "Realistic high-quality photography of traditional Mawa Modak with saffron", unsplashId: "food-15" },
  { id: 16, name: "Khoprapak (Naril Barfi)", category: "Wet Sweets", prices: { "1KG": 520, "1/2KG": 265, "250GM": 130 }, imagePrompt: "Realistic photography of coconut fudge squares (Khoprapak) with silver varq", unsplashId: "food-16" },
  { id: 17, name: "Gujiya Mawa Dryfruits", category: "Wet Sweets", prices: { "1KG": 650, "1/2KG": 330, "250GM": 170 }, imagePrompt: "Realistic high-quality photography of traditional Gujiya stuffed with mawa and dry fruits", unsplashId: "food-17" },
  { id: 18, name: "Laddu Besan", category: "Wet Sweets", prices: { "1KG": 520, "1/2KG": 260, "250GM": 130 }, imagePrompt: "Realistic photography of round golden Besan Ladoos with almonds", unsplashId: "food-18" },
  { id: 19, name: "Laddu Rava", category: "Wet Sweets", prices: { "1KG": 500, "1/2KG": 260, "250GM": 130 }, imagePrompt: "Realistic photography of textured white Rava Ladoos with raisins", unsplashId: "food-19" }
];

// Unsplash food image URLs mapped to product IDs
